e anuncios y visitas realizadas. La comisión reduce contribución; fijos y técnicos quedan fuera del CAC.","Esta instantánea es run-rate mensual con técnicos activos, no flujo de caja ni mes de capacitación. El costo del técnico empieza al contratar y su capacidad empieza el mes siguiente. No se han enviado proyecciones de caja.","[SUPUESTO] Los campos de changes son decisiones o valores editados frente al caso; no son observaciones nuevas. La mejora de respuesta/filtro y sus tasas requieren validación.","[SUPUESTO] Extrapolar adhesión de batería a futuro requiere validación. La batería solo afecta customerLtv si includeBatteryInLtv está activo; nunca se suma al resultado operativo solar ni a caja en esta consulta.","En calculateChannel, el argumento contribution recibe customerLtv; en el resultado operativo se usa solarContribution. null significa métrica no definida, nunca cero.","Ventas y visitas fraccionarias son expectativas del modelo del caso ficticio, no resultados garantizados."]};
const expectedFormulas = [{"source":"unit-economics-model.js#interpolateLeads","expression":"function interpolateLeads(investment, history) {\n    const points = history;\n    if (investment <= points[0][0]) return points[0][1];\n    for (let index = 1; index < points.length; index += 1) {\n      const [upperInvestment, upperLeads] = points[index];\n      const [lowerInvestment, lowerLeads] = points[index - 1];\n      if (investment <= upperInvestment) {\n        const share = (investment - lowerInvestment) / (upperInvestment - lowerInvestment);\n        return lowerLeads + share * (upperLeads - lowerLeads);\n      }\n    }\n    return points[points.length - 1][1];\n  }"},{"source":"unit-economics-model.js#calculateChannel.interpolatedLeads","expression":"const interpolatedLeads = channel.leadMethod === 'constant-cpl'\n      ? channel.investment / channel.assumedCpl\n      : interpolateLeads(channel.investment, channel.history);"},{"source":"unit-economics-model.js#calculateChannel.leads","expression":"const leads = interpolatedLeads * leadRetentionPercent / 100;"},{"source":"unit-economics-model.js#calculateChannel.contacts","expression":"const contacts = leads * channel.rates.contact / 100;"},{"source":"unit-economics-model.js#calculateChannel.bookings","expression":"const bookings = contacts * channel.rates.booking / 100;"},{"source":"unit-economics-model.js#calculateChannel.requestedVisits","expression":"const requestedVisits = bookings * channel.rates.visit / 100;"},{"source":"unit-economics-model.js#calculateChannel.realizedVisits","expression":"const realizedVisits = Math.min(requestedVisits, Math.max(0, availableCapacity));"},{"source":"unit-economics-model.js#calculateChannel.sales","expression":"const sales = realizedVisits * channel.rates.close / 100;"},{"source":"unit-economics-model.js#calculateChannel.cpl","expression":"const cpl = interpolatedLeads > 0 ? channel.investment / interpolatedLeads : null;"},{"source":"unit-economics-model.js#calculateChannel.adCac","expression":"const adCac = sales > 0 ? channel.investment / sales : null;"},{"source":"unit-economics-model.js#calculateChannel.realCac","expression":"const realCac = sales > 0 ? (channel.investment + realizedVisits * visitCost) / sales : null;"},{"source":"unit-economics-model.js#calculateChannel.visitsPerSale","expression":"const visitsPerSale = sales > 0 ? realizedVisits / sales : null;"},{"source":"unit-economics-model.js#calculateChannel.visitValue","expression":"const visitValue = contribution * channel.rates.close / 100 - visitCost;"},{"source":"unit-economics-model.js#calculateModel.solarContribution","expression":"const solarContribution = inputs.installationPrice * (inputs.grossMarginPercent - inputs.commissionPercent) / 100;"},{"source":"unit-economics-model.js#calculateModel.batteryContribution","expression":"const batteryContribution = inputs.batteryPrice * (inputs.batteryGrossMarginPercent - inputs.batteryCommissionPercent) / 100;"},{"source":"unit-economics-model.js#calculateModel.expectedBatteryContribution","expression":"const expectedBatteryContribution = batteryContribution * inputs.batteryAttachPercent / 100;"},{"source":"unit-economics-model.js#calculateModel.customerLtv","expression":"const customerLtv = solarContribution + (inputs.includeBatteryInLtv ? expectedBatteryContribution : 0);"},{"source":"unit-economics-model.js#calculateModel.capacity","expression":"const capacity = inputs.baseVisitCapacity + inputs.extraTechnicians * inputs.extraTechnicianCapacity;"},{"source":"unit-economics-model.js#calculateModel.initialGoogle","expression":"const initialGoogle = calculateChannel(inputs.channels.google, capacity, inputs.visitCost, customerLtv);"},{"source":"unit-economics-model.js#calculateModel.initialMeta","expression":"const initialMeta = calculateChannel(inputs.channels.meta, Math.max(0, capacity - initialGoogle.realizedVisits), inputs.visitCost, customerLtv);"},{"source":"unit-economics-model.js#calculateModel.sales","expression":"const sales = initialMeta.sales + initialGoogle.sales;"},{"source":"unit-economics-model.js#calculateModel.realizedVisits","expression":"const realizedVisits = initialMeta.realizedVisits + initialGoogle.realizedVisits;"},{"source":"unit-economics-model.js#calculateModel.requestedVisits","expression":"const requestedVisits = initialMeta.requestedVisits + initialGoogle.requestedVisits;"},{"source":"unit-economics-model.js#calculateModel.adSpend","expression":"const adSpend = inputs.channels.meta.investment + inputs.channels.google.investment;"},{"source":"unit-economics-model.js#calculateModel.technicianCosts","expression":"const technicianCosts = inputs.extraTechnicians * inputs.technicianMonthlyCost;"},{"source":"unit-economics-model.js#calculateModel.monthlyOperatingResult","expression":"const monthlyOperatingResult = sales * solarContribution\n      - adSpend\n      - realizedVisits * inputs.visitCost\n      - inputs.fixedMonthlyCosts\n      - technicianCosts;"},{"source":"unit-economics-model.js#calculateModel.totalAdCac","expression":"const totalAdCac = sales > 0 ? adSpend / sales : null;"},{"source":"unit-economics-model.js#calculateModel.totalRealCac","expression":"const totalRealCac = sales > 0 ? (adSpend + realizedVisits * inputs.visitCost) / sales : null;"},{"source":"unit-economics-model.js#calculateModel.ltvToCac","expression":"const ltvToCac = totalRealCac ? customerLtv / totalRealCac : null;"}];
